examples.code:
def double(n):
    return n * 2

assert double(4) == 8
print("first test passed")

try:
    assert double(2) == 5, "double(2) should be 4"
except AssertionError as error:
    print("test failed:", error)

def is_even(n):
    return n % 2 == 0

cases = [(2, True), (3, False), (0, True), (-4, True)]
for value, expected in cases:
    result = is_even(value)
    print(value, "ok" if result == expected else "FAIL")

def average(numbers):
    return sum(numbers) / len(numbers)

print(average([2, 4]))
try:
    print(average([]))
except ZeroDivisionError:
    print("bug: an empty list crashes the function")

exercises.solution:
def average(numbers):
    if not numbers:
        return 0
    return sum(numbers) / len(numbers)

